const PROJECT_HELP={
 'Cybersecurity':{make:'A document or simple webpage showing five made-up emails, with an explanation of the warning signs in each one.',learn:'Practise recognising suspicious requests and explaining security decisions.',output:'Five synthetic messages, your annotations, and a short explanation of how you checked your reasoning.',steps:[['Plan your five examples','Choose five fictional scenarios, such as a password request or a fake prize message. Never include real passwords or private messages.','A list of five fictional message scenarios.'],['Create and explain the examples','Write each made-up message. Beside it, explain which details are suspicious and how someone could verify the request independently. A document is enough; a website is optional.','Five messages with your explanations beside them.'],['Check your explanations','Compare your reasoning with the learning resources. Ask a teacher to review it if possible. Record anything you corrected; do not claim a review that did not happen.','Notes about what you checked and any changes you made.'],['Describe your contribution','Write what you personally created, what you learned, and what still needs work. Add a shareable project or report link if you have one.','A short project summary and an optional evidence link.']]},
 'Web Development':{make:'A small website that helps students find accessible campus facilities, such as ramps, lifts, or accessible entrances.',learn:'Practise structuring information, building a usable interface, and checking accessibility.',output:'A working directory, a source note for its information, and a short accessibility test report.',steps:[['Choose a small area','Pick one building and decide which facilities to include. Use verified information, label unknown details, and avoid collecting personal information.','A list of facilities and the information each entry needs.'],['Build the first version','Create a small list or directory with clear headings and labels. Add search or filters only after the basic information is readable.','A usable first version with a few example entries.'],['Test and improve it','Try it on a phone and with a keyboard. Check that labels make sense. Record the issues you found and what you changed.','A test log with observations and improvements.'],['Document and share','Explain your role, tools, information sources, and remaining limitations. Add a repository or demo link when available.','A README or report with a demo or repository link.']]},
 'Data Analytics':{make:'A short report explaining when a library or lab is busiest, using clearly labelled synthetic data.',learn:'Practise asking a question, checking data quality, analysing it, and explaining limitations.',output:'A dataset, reproducible calculations, a useful chart, and a written conclusion.',steps:[['Define one question','Choose one resource and one question, such as which weekday hours have the highest recorded use. Plan a synthetic dataset and label it clearly.','A question, column definitions, and a small sample dataset.'],['Clean and analyse the data','Check missing values and units. Use a spreadsheet or a tool you understand to calculate a meaningful comparison. Keep your calculations.','A documented dataset and reproducible calculations.'],['Check your conclusion','Review your formulas and sample sizes. Choose a clear chart. Explain what your data can and cannot establish.','A chart with a checked calculation and limitations.'],['Write your report','Summarise the question, approach, findings, and your contribution. Link the report or workbook if you choose.','A readable report and an optional evidence link.']]},
 'Software Engineering':{make:'A small helpdesk app that records a request and moves it through clear states such as new, in progress, and resolved.',learn:'Practise breaking down a problem, validating input, and testing behaviour.',output:'A small app, test cases, and an explanation of your design decisions.',steps:[['Define the behaviour','Write down who uses the app, what a request contains, and which status changes are allowed. Start with a small local prototype.','A short requirements list and a status transition plan.'],['Implement a small version','Create, display, and update a request using your chosen tools. Validate required input before adding extra features.','A working local prototype with the essential actions.'],['Test the important cases','Try empty requests and invalid status changes, as well as the normal flow. Record expected and actual results.','A test log and fixes for the issues you found.'],['Explain your decisions','Document the setup, your role, the tests, and what is unfinished. Link your work when ready.','A README and an optional repository or demonstration link.']]},
 'Accounting':{make:'A fictional student society ledger that tracks money received, expenses, and a monthly reconciliation.',learn:'Practise transaction records, reconciliation, and explaining differences.',output:'A fictional ledger, supporting examples, and a monthly summary.',steps:[['Plan fictional transactions','Define a small set of income and expense categories. Write sample transactions and label the entire case as fictional.','A transaction list with dates, amounts, and supporting notes.'],['Build the ledger','Record the transactions in a spreadsheet. Keep formulas and references understandable.','A structured ledger with totals that can be traced.'],['Reconcile and investigate','Compare the ledger with a fictional statement. Explain differences and record supported adjustments.','A reconciliation with documented differences.'],['Prepare a short report','Explain your process, controls, and contribution. Keep it clearly separate from real financial advice or records.','A sample monthly report and optional workbook link.']]},
 'Marketing':{make:'A small campaign concept encouraging students to repair an item rather than replace it.',learn:'Practise audience research, messaging, and honest measurement.',output:'A problem brief, two message ideas, and a small evaluation report.',steps:[['Understand the audience','Ask consenting volunteers about a recent repair experience. Avoid leading questions and record no unnecessary personal details.','An anonymised summary of needs and barriers.'],['Create two message ideas','Use your research to write two campaign messages. Define the action you hope the messages will encourage.','Two messages and a clear campaign objective.'],['Evaluate the ideas','Ask for feedback or run a small agreed comparison. Explain sample limits and report actual observations rather than invented results.','Feedback notes, measurement definitions, and limitations.'],['Tell the project story','Describe the research, decisions, your contribution, and what you would change next.','A concise campaign case study.']]},
 'Mechanical Design':{make:'A documented concept for a small, repairable desk clamp, with drawings and a plan to check its requirements.',learn:'Practise requirements, design decisions, and verification planning.',output:'A design brief, sketches or CAD model, and a check plan. A render alone does not establish safety.',steps:[['Write the requirements','Specify the intended function, dimensions, and controlled demonstration conditions. Ask a subject teacher to review the scope.','A measurable design brief with assumptions.'],['Develop a concept','Sketch alternatives and model a small concept. Explain your material and manufacturing assumptions.','Sketches or a CAD concept with design notes.'],['Plan and review checks','Identify suitable calculations, inspections, or tests with a teacher. Record what is still unvalidated. Do not attempt unsafe load tests.','A requirement-linked verification plan and review notes.'],['Document the outcome','Explain the design revisions, your role, and the limits of the concept.','A design report with drawings and an optional file link.']]},
 'UI/UX Design':{make:'A prototype that helps a new student find a campus support service and understand the next action.',learn:'Practise user research, accessible interaction, and usability testing.',output:'A task flow, a clickable prototype or paper screens, and a record of improvements.',steps:[['Understand one task','Choose one support service. Speak with consenting volunteers or review public information to understand the task and confusing terms.','A user task and an anonymised problem summary.'],['Make a simple prototype','Sketch the main steps. Use clear labels and explain the next action. A paper prototype is a valid first version.','A flow and a small set of connected screens.'],['Observe and improve','Give volunteers a realistic task without telling them which controls to use. Record observations and revise the confusing parts.','Usability observations and before/after changes.'],['Write the case study','Explain the problem, your contribution, decisions, feedback, and limitations.','A case study with a prototype link or images.']]},
 'Cloud Computing':{make:'A small cloud deployment plan that explains access permissions, estimated usage, cost alerts, and how to remove resources.',learn:'Practise responsible service selection, permissions, and cost awareness.',output:'An architecture note, cost assumptions, and an alert and teardown plan. A live deployment is optional.',steps:[['Plan a tiny workload','Choose a small example app and describe its resources and usage assumptions. Work on paper first; paid services are not required.','A resource list and workload assumptions.'],['Define access and cost controls','Describe which identity needs which permissions, estimated costs, and budget notifications. Alerts are not automatic hard spending caps.','A permission table and cost-monitoring plan.'],['Check the plan','Review permissions, cost assumptions, and removal instructions. If you deploy, use authorised resources and record the actual steps.','A reviewed checklist and any demonstration notes.'],['Explain your work','Document your role, assumptions, limitations, and how to remove any resources you created.','A project report and optional demo link.']]}
};
function projectHelp(d){return PROJECT_HELP[d]||{make:`A small study of a real local problem related to ${d}, scoped with a subject teacher.`,learn:'Practise defining a question, making a small demonstration, and explaining evidence.',output:'A problem brief, a small demonstration, feedback notes, and your contribution summary.',steps:[['Define a small problem','Describe who has the problem and ask a subject teacher to help confirm a suitable scope.','A one-page problem brief.'],['Make a first demonstration','Choose a small, safe way to explore your proposed approach using appropriate tools.','A first version, study, or documented demonstration.'],['Check and improve','Evaluate the work against your question and seek relevant feedback. Record limitations.','A check log with revisions.'],['Explain what you did','Describe your own contribution, evidence, and next steps.','A project summary and optional evidence link.']]}}
function projects(){const g=info(),h=projectHelp(domain());return `${chapterHero('projects',{kicker:'Your project workshop',title:`From “I learned it”<br><em>to “I built this.”</em>`,description:'Create something you understand and feel proud to explain. A clear idea, small practical steps, and a record of your own work.',tag:esc(domain()),metric:String(state.projects.length).padStart(2,'0'),label:state.projects.length===1?'project in your workspace':'projects in your workspace',action:'<a class="primary" href="#project-idea">Explore your project idea '+I('arrow-down')+'</a>'})}<div class="project-how"><div><b>01</b><span>Choose an idea<small>Understand what you will make</small></span></div><div><b>02</b><span>Build on your device<small>Use your own tools, at your pace</small></span></div><div><b>03</b><span>Save your progress<small>Record what you did in each step</small></span></div></div><div class="project-summary"><span>${I('flame')} <b>${streak()}</b> day learning streak</span><span>${I('check-check')} <b>${state.completed.length}</b> learning tasks completed</span><span>Project progress is self-recorded; it does not certify a skill.</span></div><article class="card project-brief" id="project-idea"><div class="project-brief-title"><span class="tag">SUGGESTED FOR ${esc(domain().toUpperCase())}</span><h2>${esc(g.project[0])}</h2></div><div class="brief-grid"><div><h3>${I('package-open')} What will I make?</h3><p>${esc(h.make)}</p></div><div><h3>${I('lightbulb')} Why am I doing this?</h3><p>${esc(h.learn)}</p></div><div><h3>${I('files')} What should I have at the end?</h3><p>${esc(h.output)}</p></div></div><div class="brief-actions"><button class="primary" id="start-project">${state.projects.some(p=>p.domain===domain())?'Continue this project':'Start this guided project'} ${I('arrow-right')}</button><button class="text-button" data-go="roadmap">Learn the foundations first ${I('book-open')}</button></div><p class="field-note">You create the work on your own device. This page guides your steps and saves your notes; it does not build or verify the project for you.</p></article><div class="section-title section-space"><h2>Projects you have started</h2><span>${state.projects.length} ${state.projects.length===1?'project':'projects'}</span></div>${state.projects.length?state.projects.map((p,i)=>{const help=projectHelp(p.domain),n=p.steps.filter(Boolean).length,next=p.steps.findIndex(x=>!x);return `<article class="card journal-card" id="project-${i}"><div class="row-between"><div><span class="tag">${esc(p.domain)}</span><h3>${esc(p.title)}</h3></div><span class="completion-label">${n} / 4 steps</span></div><div class="progress"><span style="width:${n/4*100}%"></span></div><div class="project-next"><span class="small-label">${next<0?'ALL FOUR STEPS RECORDED':'YOUR NEXT STEP'}</span><h3>${next<0?'Review your work and ask for feedback':`${next+1}. ${esc(help.steps[next][0])}`}</h3><p>${esc(next<0?'Your notes are self-recorded. Check the evidence before describing the work in your resume.':help.steps[next][1])}</p>${next<0?'':`<button class="primary" data-project-step="${next}" data-project-index="${i}">Show me what to do ${I('arrow-right')}</button>`}</div><div class="project-step-list">${help.steps.map((step,j)=>`<button class="project-step ${p.steps[j]?'finished':j===next?'current-step':''}" data-project-step="${j}" data-project-index="${i}" ${j>0&&!p.steps[j-1]?'disabled':''}><span>${p.steps[j]?I('check'):String(j+1).padStart(2,'0')}</span><div><strong>${esc(step[0])}</strong><small>${p.steps[j]?'Your completion note is saved':j===next?'Ready to start':'Finish the previous step first'}</small></div>${I(p.steps[j]?'pencil':j===next?'arrow-up-right':'lock-keyhole')}</button>`).join('')}</div><label>Project or report link (optional)<input type="url" data-evidence="${i}" value="${esc(p.evidence||'')}" placeholder="https://your-project-or-report"></label></article>`}).join(''):'<div class="empty"><h3>You haven’t started a project yet.</h3><p>Read the idea above, then choose “Start this guided project”. We’ll show you the first small step.</p></div>'}`}
function bindProjectSteps(){document.querySelectorAll('[data-project-step]').forEach(b=>b.onclick=()=>openProjectStep(Number(b.dataset.projectIndex),Number(b.dataset.projectStep)))}
function openProjectStep(i,j){const p=state.projects[i],h=projectHelp(p.domain),step=h.steps[j];if(j>0&&!p.steps[j-1])return;$('#modal-title').textContent=`Step ${j+1}: ${step[0]}`;$('#modal-body').innerHTML=`<span class="tag">${esc(p.title)} · STEP ${j+1} OF 4</span><h3>Here’s what to do</h3><p class="concept-text">${esc(step[1])}</p><div class="worked-example"><strong>What to produce for this step</strong><p>${esc(step[2])}</p></div><p>Do the work with your own tools, then come back and record it here. You can save a draft before finishing.</p><form id="step-note-form"><label>What have you done?<textarea id="step-note" maxlength="4000" placeholder="Describe your work, decisions, and anything you still need help with.">${esc(p.notes?.[j]||'')}</textarea></label><div class="button-row"><button class="primary" type="submit">Save note & finish this step ${I('check')}</button><button class="secondary" type="button" id="save-step-draft">Save draft only</button></div><p class="field-note">This is your own progress record. Saving a note is not independent verification of the work.</p></form>`;$('#modal').showModal();$('#modal').scrollTop=0;icons();const saveNote=()=>{p.notes=p.notes||['','','',''];p.notes[j]=$('#step-note').value.trim();save()};$('#save-step-draft').onclick=()=>{saveNote();notify('Draft saved. You can return to this step anytime.')};$('#step-note-form').onsubmit=e=>{e.preventDefault();if(!$('#step-note').value.trim()){notify('First, describe the work you completed for this step.');$('#step-note').focus();return}saveNote();p.steps[j]=true;save();$('#modal').close();document.querySelector(`#project-${i}`)?.scrollIntoView({block:'start',behavior:motion?'smooth':'auto'});notify('Step recorded. Your next step is ready.')}}
